def add_labels(apps, schema_editor):
    """The «تمرین» box (numbered, its solution shown on a tap) and «پرسش و پاسخ». A label of that name made in the
    panel already is left as it is."""
    Label = apps.get_model("catalog", "Label")
    order = (Label.objects.order_by("-order").values_list("order", flat=True).first() or 0) + 10
    for i, (name, style, numbered, icon, aliases) in enumerate(NEW_LABELS):
        Label.objects.get_or_create(
            name=name,
            defaults={"group": "عمومی", "style": style, "numbered": numbered, "icon": icon, "aliases": aliases, "order": order + 10 * i},
        )


